type Box=readonly[number,number,number,number];const boxes:Box[]=[[0,0,2,2],[1,0,3,2],[4,0,6,2]];export function iou(a:Box,b:Box){const area=(v:Box)=>(v[2]-v[0])*(v[3]-v[1]),inter=Math.max(0,Math.min(a[2],b[2])-Math.max(a[0],b[0]))*Math.max(0,Math.min(a[3],b[3])-Math.max(a[1],b[1]));return inter/(area(a)+area(b)-inter);}export function suppress(cutoff:number,scores=[.9,.8,.7],order=[0,1,2]){const ranked=[...order].sort((a,b)=>scores[b]-scores[a]),kept:number[]=[],removed:number[]=[];for(const i of ranked){if(kept.some(j=>iou(boxes[i],boxes[j])>cutoff))removed.push(i);else kept.push(i);}return {boxes,scores,ranked,kept,removed,cutoff,overlap:iou(boxes[0],boxes[1])};}export function run(mode:number){return suppress(mode===1?.5:mode===2?1/3:.3);}

function Picture({mode}:{mode:number}){const r=m.run(mode);return <svg className={s.plot} viewBox="0 0 280 118" role="img" aria-label="Who survives the cutoff? — worked example">{r.boxes.map((b,i)=><g key={i}><rect x={8+b[0]*28} y="26" width="56" height="45" className={r.kept.includes(i)?s.box:s.removed}/><text x={i===1?53:16+b[0]*28} y="20">{String.fromCharCode(65+i)}:{r.scores[i]}</text></g>)}<text x="6" y="94">IoU(A,B)={f(r.overlap,3)} · cutoff={f(r.cutoff,3)}</text><text x="6" y="113">keep {r.kept.map(i=>String.fromCharCode(65+i)).join(',')}</text></svg>;}

Locked inputs: A=[0,0,2,2]:.9; B=[1,0,3,2]:.8; C=[4,0,6,2]:.7. Same class; suppress if IoU>cutoff.
